int main() {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);              // 1. create
    if (server_fd == -1) { perror("socket"); return 1; }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));   // restart without waiting

    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;                            // all network interfaces
    addr.sin_port = htons(5050);                                  // host -> network byte order

    if (bind(server_fd, (sockaddr*)&addr, sizeof(addr)) == -1) { perror("bind"); return 1; }  // 2. bind
    listen(server_fd, 5);                                         // 3. listen
    std::cout << "Server waiting on port 5050...\n";

    int client_fd = accept(server_fd, nullptr, nullptr);          // 4. accept (blocks)
    char buf[256];
    ssize_t n = recv(client_fd, buf, sizeof(buf) - 1, 0);         // 5. receive
    if (n > 0) {
        buf[n] = '\0';
        std::cout << "Server got: " << buf << "\n";
        const char* reply = "Hello from server";
        send(client_fd, reply, strlen(reply), 0);                 //    reply
    }
    close(client_fd);                                             // 6. close
    close(server_fd);
}

