#include <cerrno>
#include <cstddef>
#include <sys/socket.h>
#include <sys/types.h>

// Send exactly 'len' bytes. Returns 0 on success, -1 on error.
int sendAll(int fd, const void* data, size_t len) {
    const char* p = static_cast<const char*>(data);
    while (len > 0) {
        ssize_t n = send(fd, p, len, MSG_NOSIGNAL);
        if (n == -1) { if (errno == EINTR) continue; return -1; }
        p += n;
        len -= static_cast<size_t>(n);
    }
    return 0;
}

// Receive exactly 'len' bytes. Returns 0 on success, 0-length close = -2, error = -1.
int recvAll(int fd, void* data, size_t len) {
    char* p = static_cast<char*>(data);
    while (len > 0) {
        ssize_t n = recv(fd, p, len, 0);
        if (n == 0) return -2;                      // peer closed the connection
        if (n == -1) { if (errno == EINTR) continue; return -1; }
        p += n;
        len -= static_cast<size_t>(n);
    }
    return 0;
}

