#include <iostream>
#include <semaphore.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <unistd.h>

struct Shared {
    sem_t lock;
    int counter;
};

int main() {
    auto* s = static_cast<Shared*>(mmap(nullptr, sizeof(Shared), PROT_READ | PROT_WRITE,
                                        MAP_SHARED | MAP_ANONYMOUS, -1, 0));
    s->counter = 0;
    sem_init(&s->lock, 1, 1);                    // pshared = 1 (between processes), start value 1

    for (int p = 0; p < 2; ++p) {
        if (fork() == 0) {
            for (int i = 0; i < 50000; ++i) {
                sem_wait(&s->lock);              // enter critical section
                s->counter++;
                sem_post(&s->lock);              // leave critical section
            }
            std::cout.flush(); _exit(0);
        }
    }
    wait(nullptr); wait(nullptr);
    std::cout << "counter = " << s->counter << "\n";   // 100000
    sem_destroy(&s->lock);
}

#include <iostream>
#include <semaphore.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <unistd.h>

struct Shared {
    sem_t empty;       // free slots
    sem_t full;        // filled slots
    int value;         // one-slot buffer
};

int main() {
    auto* s = static_cast<Shared*>(mmap(nullptr, sizeof(Shared), PROT_READ | PROT_WRITE,
                                        MAP_SHARED | MAP_ANONYMOUS, -1, 0));
    sem_init(&s->empty, 1, 1);                   // one free slot at start
    sem_init(&s->full, 1, 0);                    // nothing to consume at start

    if (fork() == 0) {                           // consumer
        for (int i = 0; i < 5; ++i) {
            sem_wait(&s->full);                  // wait until data is there
            std::cout << "Consumer got " << s->value << "\n";
            sem_post(&s->empty);                 // slot is free again
        }
        std::cout.flush(); _exit(0);
    }
    for (int i = 1; i <= 5; ++i) {               // producer
        sem_wait(&s->empty);                     // wait for a free slot
        s->value = i * 10;
        sem_post(&s->full);                      // tell consumer: data ready
    }
    wait(nullptr);
    sem_destroy(&s->empty); sem_destroy(&s->full);
}

#include <cerrno>
