#include <pthread.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <unistd.h>

struct Shared {
    pthread_mutex_t m;
    int counter;
};

int main() {
    auto* s = static_cast<Shared*>(mmap(nullptr, sizeof(Shared), PROT_READ | PROT_WRITE,
                                        MAP_SHARED | MAP_ANONYMOUS, -1, 0));
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);   // works across processes
    pthread_mutexattr_setrobust(&attr, PTHREAD_MUTEX_ROBUST);      // survives owner crash
    pthread_mutex_init(&s->m, &attr);
    s->counter = 0;

    for (int p = 0; p < 2; ++p) {
        if (fork() == 0) {
            for (int i = 0; i < 50000; ++i) {
                if (pthread_mutex_lock(&s->m) == EOWNERDEAD)
                    pthread_mutex_consistent(&s->m);              // previous owner died
                s->counter++;
                pthread_mutex_unlock(&s->m);
            }
            std::cout.flush(); _exit(0);
        }
    }
    wait(nullptr); wait(nullptr);
    std::cout << "counter = " << s->counter << "\n";               // 100000
    pthread_mutex_destroy(&s->m);
}

