    wait(nullptr);
}

#include <arpa/inet.h>
#include <fcntl.h>
#include <iostream>
#include <netinet/in.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <unistd.h>

int main() {
    int srv = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(7070);
    bind(srv, (sockaddr*)&addr, sizeof(addr));
    listen(srv, 128);

    int ep = epoll_create1(0);                              // create epoll instance
    epoll_event ev{};
    ev.events = EPOLLIN;
    ev.data.fd = srv;
    epoll_ctl(ep, EPOLL_CTL_ADD, srv, &ev);                 // watch the listening socket

    epoll_event events[64];
    for (;;) {
        int n = epoll_wait(ep, events, 64, -1);             // sleep until something is ready
        for (int i = 0; i < n; ++i) {
            int fd = events[i].data.fd;
            if (fd == srv) {                                // new client
                int c = accept(srv, nullptr, nullptr);
                epoll_event cev{};
                cev.events = EPOLLIN;
                cev.data.fd = c;
                epoll_ctl(ep, EPOLL_CTL_ADD, c, &cev);
            } else {                                        // data from a client
                char buf[512];
                ssize_t r = recv(fd, buf, sizeof(buf), 0);
                if (r <= 0) {                               // closed or error
                    epoll_ctl(ep, EPOLL_CTL_DEL, fd, nullptr);
                    close(fd);
                } else {
                    send(fd, buf, r, 0);                    // echo
                }
            }
        }
    }
}

#include <iostream>
