#include <sys/wait.h>
#include <unistd.h>

int main() {
    int fd[2];
    pipe(fd);
    if (fork() == 0) {                                  // child writes after 1 second
        close(fd[0]);
        sleep(1);
        if (write(fd[1], "data", 4) == -1) perror("write");
        std::cout.flush(); _exit(0);
    }
    close(fd[1]);

    fd_set readfds;
    FD_ZERO(&readfds);                                  // must be rebuilt before each select()
    FD_SET(fd[0], &readfds);
    timeval tv{3, 0};                                   // wait at most 3 seconds

    int ready = select(fd[0] + 1, &readfds, nullptr, nullptr, &tv);
    if (ready > 0 && FD_ISSET(fd[0], &readfds)) {
        char buf[16];
        ssize_t n = read(fd[0], buf, sizeof(buf) - 1);
        buf[n] = '\0';
        std::cout << "Ready, read: " << buf << "\n";
    } else if (ready == 0) {
        std::cout << "Timeout\n";
    }
    wait(nullptr);
}

