#include <sys/eventfd.h>
#include <sys/wait.h>
#include <unistd.h>

int main() {
    int efd = eventfd(0, 0);
    if (fork() == 0) {                                  // child waits for the event
        uint64_t value;
        if (read(efd, &value, sizeof(value)) == sizeof(value))   // blocks until the counter is > 0
            std::cout << "Child woke up, value = " << value << "\n";
        std::cout.flush(); _exit(0);
    }
    sleep(1);
    uint64_t one = 1;
    if (write(efd, &one, sizeof(one)) == -1) perror("write");    // wake the child
    wait(nullptr);
    close(efd);
}

