#include <atomic>
#include <iostream>
#include <new>
#include <sched.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <unistd.h>

constexpr size_t N = 8;                                   // capacity

struct Ring {
    std::atomic<size_t> head{0};                          // written only by the producer
    std::atomic<size_t> tail{0};                          // written only by the consumer
    int data[N];

    bool push(int v) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h - tail.load(std::memory_order_acquire) == N) return false;   // full
        data[h % N] = v;
        head.store(h + 1, std::memory_order_release);     // publish after the data is written
        return true;
    }
    bool pop(int& v) {
        size_t t = tail.load(std::memory_order_relaxed);
        if (t == head.load(std::memory_order_acquire)) return false;       // empty
        v = data[t % N];
        tail.store(t + 1, std::memory_order_release);
        return true;
    }
};

int main() {
    void* mem = mmap(nullptr, sizeof(Ring), PROT_READ | PROT_WRITE,
                     MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    Ring* ring = new (mem) Ring();                        // construct in shared memory

    if (fork() == 0) {                                    // consumer
        int sum = 0, v, got = 0;
        while (got < 20) {
            if (ring->pop(v)) { sum += v; ++got; }
            else sched_yield();
        }
        std::cout << "Consumer sum = " << sum << "\n";    // 210
        std::cout.flush(); _exit(0);
    }
    for (int i = 1; i <= 20; ++i)                         // producer
        while (!ring->push(i)) sched_yield();
    wait(nullptr);
    munmap(mem, sizeof(Ring));
}
